1. `import { api } from 'utility'`를 `import {.apiRest } from 'api-rest-' 형식으로 변경합니다.
2. 사용하는 곳에서 `api...~` 의 경우 다음 형식으로 변경됩니다. `apiRest.~`

아래의 변환 스크립트는 주어진 코드를 리팩토링하기 위한 것입니다.
```javascript
module.exports = function transformer(fileInfo, api) {
  const j = api.jscodeshift;
  const root = j(fileInfo.source);

  // Find all api.<name> usages
  const apiUsages = root.find(j.MemberExpression, {
    object: { name: 'api' },
  });

  // Extract <name> from api.<name>
  const apiNames = new Set(
    apiUsages.nodes().map((node) => node.property.name)
  );

  // Change import statement for each <name>
  apiNames.forEach((name) => {
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1)}`;

    // Add pure|impure to the new name
    const pureOrImpure = name === 'designHub' ? 'Pure' : 'Impure';
    const finalNewName = `${newName}${pureOrImpure}`;

    root
      .find(j.ImportDeclaration, {
        source: { value: 'utility' },
      })
      .find(j.ImportSpecifier)
      .forEach((specifier) => {
        if (specifier.node.imported.name === 'api') {
          specifier.node.imported.name = finalNewName;
          specifier.node.local.name = finalNewName;
        }
      });

    root
      .find(j.ImportDeclaration, {
        source: { value: 'utility' },
      })
      .replaceWith(
        j.importDeclaration(
          [j.importSpecifier(j.identifier(finalNewName))],
          j.literal(`api-rest-${name}`)
        )
      );
  });

  // Change api usages for each <name>
  apiUsages.forEach((memberExpression) => {
    const name = memberExpression.node.property.name;
    const newName = `api${name[0].toUpperCase() + name.slice(1)}`;

    // Add pure|impure to the new name
    const pureOrImpure = name === 'designHub' ? 'Pure' : 'Impure';
    const finalNewName = `${newName}${pureOrImpure}`;

    memberExpression.node.object.name = finalNewName;
  });

  return root.toSource({ quote: 'single' });
};
```
변환 스크립트를 사용하여 리팩토링을 수행하려면:
```bash
jscodeshift -t refactor-imports.js <source-file>
```
`<source-file>`은 리팩토링하려는 파일의 경로를 지정해야 합니다. 이 변환 스크립트는 주어진 코드를 필요한 형식으로 리팩토링합니다.

아래의 변환 스크립트는 원하는대로 리팩토링을 수행합니다.
```javascript
module.exports = function transformer(fileInfo, api) {
  const j = api.jscodeshift;
  const root = j(fileInfo.source);

  // Find all api.<name>.<pure|impure> usages
  const apiUsages = root.find(j.MemberExpression, {
    object: { type: 'MemberExpression', object: { name: 'api' } },
  });

  // Extract <name> and <pure|impure> from api.<name>.<pure|impure>
  const apiNames = new Map();
  apiUsages.nodes().forEach((node) => {
    const name = node.object.property.name;
    const pureOrImpure = node.property.name;
    if (!apiNames.has(name)) {
      apiNames.set(name, []);
    }
    if (!apiNames.get(name).includes(pureOrImpure)) {
      apiNames.get(name).push(pureOrImpure);
    }
  });

  // Change import statement and api usages for each <name> and <pure|impure>
  apiNames.forEach((pureOrImpureList, name) => {
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1)}`;

    pureOrImpureList.forEach((pureOrImpure) => {
      const finalNewName = `${newName}${pureOrImpure[0].toUpperCase() + pureOrImpure.slice(1)}`;

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .find(j.ImportSpecifier)
        .forEach((specifier) => {
          if (specifier.node.imported.name === 'api') {
            specifier.node.imported.name = finalNewName;
            specifier.node.local.name = finalNewName;
          }
        });

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .replaceWith(
          j.importDeclaration(
            [j.importSpecifier(j.identifier(finalNewName))],
            j.literal(`api-rest-${name}`)
          )
        );
    });
  });

  // Change api usages for each <name> and <pure|impure>
  apiUsages.forEach((memberExpression) => {
    const name = memberExpression.node.object.property.name;
    const pureOrImpure = memberExpression.node.property.name;
    const newName = `api${name[0].toUpperCase() + name.slice(1)}`;
    const finalNewName = `${newName}${pureOrImpure[0].toUpperCase() + pureOrImpure.slice(1)}`;

    memberExpression.node.object = j.identifier(finalNewName);
  });

  return root.toSource({ quote: 'single' });
};
```
변환 스크립트를 사용하여 리팩토링을 수행하려면:
```bash
jscodeshift -t refactor-imports.js <source-file>
```
`<source-file>`은 리팩토링하려는 파일의 경로를 지정해야 합니다. 이 변환 스크립트는 주어진 코드를 필요한 형식으로 리팩토링합니다.

먼저 이해를 돕기 위해, 이 변환 스크립트는 jscodeshift를 사용하여 주어진 코드를 리팩토링합니다. 주요 변경 사항은 다음과 같습니다:

1. `import { api } from 'utility'`를 `import {.apiRest<package><pure|impure> } from 'api-rest-<package>'` 형식으로 변경합니다.
2. 사용하는 곳에서 `api.<package>.<pure|impure>.~` 의 경우 다음 형식으로 변경됩니다. `apiRest<package><pure|impure>.~`

변환 스크립트의 주요 부분을 단계별로 설명하겠습니다:

1. 코드에서 `api` 객체의 사용을 찾아 `apiUsages`에 저장합니다. 이 객체의 사용은 `api.<package>.<pure|impure>` 형식입니다.
```javascript
const apiUsages = root.find(j.MemberExpression, {
  object: { type: 'MemberExpression', object: { name: 'api' } },
