타입스크립트에 맞게 변환 스크립트를 수정하려면, 먼저 `@ts-morph/bootstrap` 패키지를 설치하고 사용해야 합니다. 이전에 설명한 방법으로 `@ts-morph/bootstrap`을 설치하고, 아래와 같이 변환 스크립트를 수정하세요.
```javascript
const { createProject } = require("@ts-morph/bootstrap");

module.exports = async function transformer(fileInfo, api) {
  const j = api.jscodeshift;
  const { source } = fileInfo;

  const { project, sourceFile } = await createProject({ useInMemoryFileSystem: true }, { skipAddingFilesFromTsConfig: true });
  project.createSourceFile("temp.ts", source);
  const text = sourceFile.getFullText();

  const root = j(text);

  // Find all api.<name>.<pure|impure> usages
  const apiUsages = root.find(j.MemberExpression, {
    object: { object: { name: 'api' }, type: 'MemberExpression' },
  });

  // Extract <name> and <pure|impure> from api.<name>.<pure|impure>
  const apiNames = new Map();
  apiUsages.nodes().forEach((node) => {
    const { name } = node.object.property;
    const pureOrImpure = node.property.name;
    if (!apiNames.has(name)) {
      apiNames.set(name, []);
    }
    if (!apiNames.get(name).includes(pureOrImpure)) {
      apiNames.get(name).push(pureOrImpure);
    }
  });

  // Change import statement and api usages for each <name> and <pure|impure>
  apiNames.forEach((pureOrImpureList, name) => {
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1)}`;

    pureOrImpureList.forEach((pureOrImpure) => {
      const finalNewName = `${newName}${pureOrImpure[0].toUpperCase() + pureOrImpure.slice(1)}`;

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .find(j.ImportSpecifier)
        .forEach((specifier) => {
          if (specifier.node.imported.name === 'api') {
            specifier.node.imported.name = finalNewName;
            specifier.node.local.name = finalNewName;
          }
        });

      root
        .find(j.ImportDeclaration, {
          source: { value: 'utility' },
        })
        .replaceWith(j.importDeclaration([j.importSpecifier(j.identifier(finalNewName))], j.literal(`api-rest-${name}`)));
    });
  });

  // Change api usages for each <name> and <pure|impure>
  apiUsages.forEach((memberExpression) => {
    const { name } = memberExpression.node.object.property;
    const pureOrImpure = memberExpression.node.property.name;
    const newName = `apiRest${name[0].toUpperCase() + name.slice(1)}`;
    const finalNewName = `${newName}${pureOrImpure[0].toUpperCase() + pureOrImpure.slice(1)}`;

    memberExpression.node.object = j.identifier(finalNewName);
  });

  return root.toSource({ quote: 'single' });
};
```
이제 이 스크립트는 타입스크립트와 호환됩니다. 변경 사항은 `createProject`

워커 없이 직접 변환 스크립트를 실행하려면, Node.js 런타임을 사용할 수 있습니다. 먼저, 변환 스크립트를 `transformer.js`라는 파일로 저장한 다음, 아래와 같이 실행할 수 있는 새로운 파일을 작성하세요.

예를 들어, `run-transformer.js`라는 파일을 생성하고 다음 코드를 추가하세요:
```javascript
const fs = require("fs");
const path = require("path");
const transformer = require("./transformer");

const inputFilePath = path.resolve(__dirname, "./input.ts"); // 입력 파일 경로를 수정하세요
const outputFilePath = path.resolve(__dirname, "./output.ts"); // 출력 파일 경로를 수정하세요

fs.readFile(inputFilePath, "utf8", async (err, data) => {
  if (err) {
    console.error("Error reading input file:", err);
    return;
  }

  const fileInfo = { source: data };
  const api = { jscodeshift: require("jscodeshift") };

  try {
    const transformedCode = await transformer(fileInfo, api);
    fs.writeFile(outputFilePath, transformedCode, "utf8", (err) => {
      if (err) {
        console.error("Error writing output file:", err);
      } else {
        console.log("Transformation completed. Output saved to:", outputFilePath);
      }
    });
  } catch (error) {
    console.error("Error during transformation:", error);
  }
});
```
